local k={163,145,147,216,68,207,133,202,43,212,203,203,165,17,51,43,40,56,51,214,179,252,144,253,108,66,130,178,58,177,105,40}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
